+const FANUC: &str = include_str!("../../../assets/posts/fanuc.cps");
+const BALL: &str = "BN-0600";
+
+fn ok<T, E: std::fmt::Debug>(r: Result<T, E>, what: &str) -> T {
+    r.unwrap_or_else(|e| panic!("{what}: {e:?}"))
+}
